require "rails_helper"

RSpec.describe "Owner-aware entry reads", type: :request do
  include_context "timekeeping contract fakes"

  it "shows an entry the Timekeeping owner just created, with its review status, while delivery is paused" do
    company = create(:company)
    user = create(:user, current_workspace_id: company.id)
    project = create(:project, client: create(:client, company:))
    create(:employment, company:, user:)
    user.add_role :admin, company
    create(:project_member, user:, project:)
    TimekeepingOwnership.current.update_columns(generation: 2, owner: "timekeeping", handoff_step: nil)
    allow(Timekeeping::EntryApiClient).to receive(:new)
      .and_return(TimekeepingContract::FakeEntryApiClient.new(timekeeping: fake_timekeeping))
    work_date = Date.current.iso8601
    entry_id = fake_timekeeping.add_entry(
      company_id: company.id, user_id: user.id, project_id: project.id,
      work_date:, duration: 45.0, note: "Logged while the relay is paused", review_status: "pending_review"
    ).fetch("id")
    sign_in user

    # Delivery is paused: fake_relay.deliver_pending is never called, so timesheet_entries has no row.
    # "Include a case where delivery is paused and a newly created entry still shows at once in the time-tracking index and entry list."
    [api_v1_timesheet_entry_index_path, api_v1_time_tracking_index_path].each do |path|
      send_request :get, path, params: { from: work_date, to: work_date }, headers: auth_headers(user)

      expect(response).to have_http_status(:ok)
      shown = json_response.fetch("entries").fetch(work_date).select { |entry| entry["id"] == entry_id }
      expect(shown.size).to eq(1)
      # Neither index view renders review_status, and the response shapes must not change, so the owner's
      # review status is checked on the records the reader returns instead.
      expect(shown.first).to include("note" => "Logged while the relay is paused",
                                     "project_id" => project.id, "type" => "timesheet")
    end
    expect(TimesheetEntry.unscoped.where(id: entry_id)).not_to exist

    read = Timekeeping::EntryReader.list(company_id: company.id, user_id: user.id, from: work_date, to: work_date)
    expect(read.find { |entry| entry.id == entry_id }.review_status).to eq("pending_review")
  end
end

require "rails_helper"

RSpec.describe "Timekeeping owner reads and aggregate reports", type: :request do
  it "reads the Timekeeping owner for the time-tracking index while the time entry report still reads timesheet_entries" do
    # The time entry report is a paid-plan feature, so a free company gets 403 before the report runs.
    company = create(:company, plan_tier: "paid")
    user = create(:user, current_workspace_id: company.id)
    project = create(:project, client: create(:client, company:))
    create(:employment, company:, user:)
    user.add_role :admin, company
    create(:project_member, user:, project:)
    projected = create(:timesheet_entry, user:, project:, work_date: Date.current, note: "projection only")
    fake_timekeeping = TimekeepingContract::FakeTimekeeping.new
    owner_entry = fake_timekeeping.add_entry(company_id: company.id, user_id: user.id, project_id: project.id,
                                             work_date: Date.current.iso8601, duration: 30.0, note: "owner only")
    allow(Timekeeping::EntryApiClient).to receive(:new)
      .and_return(TimekeepingContract::FakeEntryApiClient.new(timekeeping: fake_timekeeping))
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2)
    sign_in user

    send_request :get, api_v1_time_tracking_index_path, headers: auth_headers(user)
    expect(response).to have_http_status(:ok)
    index_notes = json_response["entries"].values.flatten.select { |entry| entry["type"] == "timesheet" }.pluck("note")
    expect(index_notes).to eq(["owner only"])
    expect(owner_entry.fetch("id")).not_to eq(projected.id)

    # "Aggregate reports keep reading `timesheet_entries`."
    send_request :get, api_v1_reports_time_entries_path, headers: auth_headers(user)
    expect(response).to have_http_status(:ok)
    report_ids = json_response["reports"].flat_map { |group| group["entries"].pluck("id") }
    expect(report_ids).to eq([projected.id])
  end
end
